1: // 《没弄反》 Not Swapped: the whole film as data. Layout of both boards, every stroke with its time, the sliding
2: // panel, the drying wet band, the one wipe, the camera, the texts for readcheck and the sound events.
3: // Units: world = the board's slate (x 0…6400, y 0…1700). Front-panel things are stored in panel-local units
4: // (layer 'FL'); the panel's offset slideX(t) moves them. Back-board things are in world units (layer 'BK').
5: import { clamp, lerp, ss, eio, eo } from '/core/lib.js';
6: import { Stroke, catmull, n1, rng } from './chalk.js';
7: import { writeChar, writeLine, writeLatin, latinWidth } from './hand.js';
