13: export const G1 = { x: 1150, y: 800, size: 620 }, G2 = { x: 2200, y: 800, size: 620 };   // painted grids on FL
14: export const SMALL = [{ x: 560, y: 1330, size: 300 }];                                      // one painted small grid on the back board
15: const CH = 520;                                                                              // big characters
16: // voice-over (vo/, edge-tts zh-CN-XiaoxiaoNeural +15%): lengths from vo/dur.json; the picture is timed to the voice
17: export const VO = { n1: 3.146, n2: 4.553, n3: 6.725, n4: 3.617, n5: 2.28, n6: 2.41, n7: 6.623, n8: 4.102, n9: 1.307 };
18: // subtitles: the voice as said (Chinese) and a free English translation, one line each
19: export const SUB = {
20:   n1: [['网上有个说法：射和矮，这两个字弄反了。', 'People online say the characters 射 and 矮 got swapped.']],
21:   n2: [['射字左边是身，右边是寸。', '射 is 身 (body) plus 寸 (inch).'], ['身高一寸，那不就是矮吗？', 'One inch tall: isn\u2019t that short?']],
22:   n3: [['矮字左边是矢，矢就是箭；', 'On the left of 矮 is 矢, an arrow;'], ['右边是委，有放下的意思。', 'on the right is 委, to let go.'], ['把箭放出去，那不就是射吗？', 'Letting an arrow go: isn\u2019t that shooting?']],
23:   n4: [['其实，射最早画的是一张弓，弓上搭着一支箭。', 'In fact, the oldest 射 is a bow with an arrow on it.']],
24:   n5: [['后来又加了一只手，在拉弓弦。', 'Later a hand was added, pulling the string.']],
25:   n6: [['弓慢慢写成了身，手写成了寸。', 'The bow slowly became 身, and the hand became 寸.']],
26:   n7: [['那矮里为什么有支箭？', 'Why is there an arrow in 矮?'], ['古人拿箭当尺子，用来量长短。', 'People once used arrows as rulers to measure length.'], ['所以短字里，也有这支箭。', 'That is why 短 (short) has one too.']],
27:   n8: [['射，是拉弓放箭；', '射 means drawing a bow and shooting;'], ['矮，就是个子短，委只管读音。', '矮 means short, and 委 only gives the sound.']],
28:   n9: [['所以，没弄反。', 'So they were never swapped.']],
29: };
30: const isCJK = c => /[\p{Script=Han}]/u.test(c);
31: export const needOf = txt => { let a = 0, b = 0; for (const c of txt) { if (/\s/.test(c)) continue; isCJK(c) ? a++ : b++; } return Math.max(1.5, a / 4.5 + b / 15 + 1.5); };
