33: export function build(W = 1920, H = 1080) {
34:   const S = [], TX = [], EV = [], SUBS = [];
35:   const add = (arr, layer, phase = 'pre') => { arr.forEach(s => { s.layer = layer; s.phase = phase; S.push(s); }); return arr; };
36:   const text = (id, txt, layer, strokes, t1 = 1e9, pad = 6) => {
37:     let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
38:     for (const s of strokes) for (const [x, y] of s.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
39:     TX.push({ id, text: txt, layer, box: [x0 - pad, y0 - pad, x1 + pad, y1 + pad], t0: strokes[0].t0, t1 });
40:   };
41:   const line = (pts, o, t0, dur) => { const s = new Stroke(o.smooth ? catmull(pts, 10) : pts, { kind: 'write', taper: .2, taperLen: .2, land: .6, skip: .14, endSpecks: true, specks: .6, ...o }); s.t0 = t0; s.t1 = t0 + dur; return s; };
42:   const centred = (txt, cx, cy, size, t, o = {}) => { const w = writeLine(txt, 0, 0, size, 0, o).x; return writeLine(txt, cx - w / 2, cy, size, t, o); };
43:   const centredLatin = (txt, cx, by, cap, t, o = {}) => writeLatin(txt, cx - latinWidth(txt, cap) / 2, by, cap, t, o);
44:   // a voice line and its subtitle: the subtitle stays up for its reading time; returns the earliest start of the next line
45:   const vo = (id, t) => {
46:     EV.push({ t, type: 'vo', id });
47:     const parts = SUB[id], zh = parts.map(p => p[0]).join(''), en = parts.map(p => p[1]).join(' '), end = t + VO[id], t0 = t - .08;
48:     const t1 = end + .3;                                                            // next line may start 0.35 s after this one ends
49:     // one subtitle per sentence, timed by its share of the spoken characters (a pause counts as half a character)
50:     const w = parts.map(p => [...p[0]].reduce((a, c) => a + (isCJK(c) ? 1 : /[，。；？：]/.test(c) ? .5 : 0), 0)), W0 = w.reduce((a, b) => a + b, 0);
51:     let acc = 0;
52:     parts.forEach((p, k) => {
53:       const a = k ? t + VO[id] * acc / W0 : t0; acc += w[k];
54:       const b = k === parts.length - 1 ? Math.max(end + .3, a + 1.0) : t + VO[id] * acc / W0;
55:       SUBS.push({ id: id + (parts.length > 1 ? '-' + (k + 1) : ''), t0: a, t1: b, zh: p[0], en: p[1], vend: end });
56:       EV.push({ t: +a.toFixed(3), type: 'sub', t1: +b.toFixed(3), zh: p[0], en: p[1] });     // for the .srt
57:     });
58:     T[id] = end; return t1 + .05;
59:   };
60:   const T = {};
61: 
62:   // ───────── already on the board before the film starts (front panel, top right): the date, the child's question
63:   const date = add(writeLine('10月28日 星期三', 2660, 104, 66, -20, { seed: 2, latinScale: .7, speed: 60 }), 'FL');
64:   text('date', '10月28日 星期三', 'FL', date);
65:   const kidZh = add(writeLine('射和矮弄反了吗？', 2330, 262, 104, -19, { hand: 'child', seed: 7, speed: 60 }), 'FL');
