69:   const ti = add(writeLine('汉字的故事', 1000, 252, 124, .05, { seed: 4, speed: 22 }), 'FL');
70:   const tie = add(writeLatin('The Story of Chinese Characters', 1012, 400, 46, ti.end + .04, { seed: 5, lspeed: 200 }), 'FL');
71:   text('title', '汉字的故事', 'FL', ti); text('title-en', 'The Story of Chinese Characters', 'FL', tie);
72:   EV.push({ t: .05, type: 'title' });
73:   T.title = tie.end; T.dry = ti.end + .45;
74:   const wet = { x0: 1690, y0: 160, y1: 430, xEnd: 2280, t0: ti.end - .35, t1: T.dry + .45, bx0: 1700 };
75:   let next = vo('n1', 2.1);
76:   const she = add(writeChar('射', G1.x, G1.y, CH, 2.8, { seed: 11, speed: 9, gap: .01 }), 'FL');
