83:   let t = T.s2 + .45;
84:   add([line([[L1 + 8, 1132], [M1 - 14, 1128]], { w: 8, color: 'white' }, t, .22)], 'FL');
85:   const lShen = add(writeChar('身', (L1 + M1) / 2, 1212, 100, t + .25, { seed: 12, speed: 40 }), 'FL'); t = T.s2 + 1.45;
86:   add([line([[M1 + 14, 1128], [R1 - 6, 1124]], { w: 8, color: 'white' }, t, .2)], 'FL');
