// How DNS Works: Chalkboard Film
import { clamp, lerp, ss, eio, eo } from '/core/lib.js';
import { Stroke, catmull, n1, rng } from './chalk.js';
import { writeLine, writeLatin, latinWidth } from './hand.js';
import { PW } from './stage.js';

export const VO = { n1: 3.5, n2: 4.5, n3: 5.5 };
export const SUB = {
  n1: [['When you type a website name...', 'When you type a website name...']],
  n2: [['...your computer needs an IP address.', '...your computer needs an IP address.']],
  n3: [['DNS translates example.com into 93.184.216.34.', 'DNS translates example.com into 93.184.216.34.']]
};

export const needOf = txt => Math.max(1.5, txt.length / 15 + 1.5);

export function build(W = 1920, H = 1080) {
  const S = [], TX = [], EV = [], SUBS = [];
  const add = (arr, layer = 'FL', phase = 'pre') => { arr.forEach(s => { s.layer = layer; s.phase = phase; S.push(s); }); return arr; };
  const text = (id, txt, layer, strokes, t1 = 1e9, pad = 6) => {
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (const s of strokes) for (const [x, y] of s.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
    TX.push({ id, text: txt, layer, box: [x0 - pad, y0 - pad, x1 + pad, y1 + pad], t0: strokes[0].t0, t1 });
  };
  const line = (pts, o, t0, dur) => { const s = new Stroke(o.smooth ? catmull(pts, 10) : pts, { kind: 'write', taper: .2, taperLen: .2, land: .6, skip: .14, endSpecks: true, specks: .6, ...o }); s.t0 = t0; s.t1 = t0 + dur; return s; };

  const vo = (id, t) => {
    EV.push({ t, type: 'vo', id });
    const parts = SUB[id], end = t + VO[id], t0 = t - .08;
    const t1 = end + .3;
    parts.forEach((p, k) => {
      SUBS.push({ id: id + '-' + (k + 1), t0, t1: end + .3, zh: p[0], en: p[1], vend: end });
      EV.push({ t: +t0.toFixed(3), type: 'sub', t1: +(end + .3).toFixed(3), zh: p[0], en: p[1] });
    });
    T[id] = end; return t1 + .05;
  };
  const T = {};

  // Title
  const ti = add(writeLatin('How DNS Works', 960, 220, 72, 0.2, { seed: 4, lspeed: 180 }));
  text('title', 'How DNS Works', 'FL', ti);
  EV.push({ t: 0.2, type: 'title' });

  let next = vo('n1', 2.0);

  // Domain name on the board
  const dom = add(writeLatin('example.com', 500, 550, 60, 2.5, { seed: 10, lspeed: 150 }));
  text('domain', 'example.com', 'FL', dom);

  next = vo('n2', next);

  // Phonebook / DNS label
  const dns = add(writeLatin('DNS: Internet Phonebook', 960, 420, 50, 6.0, { seed: 11, lspeed: 160 }));
  text('dns', 'DNS: Internet Phonebook', 'FL', dns);

  next = vo('n3', next);

  // Arrow and IP address
  const arr = line([[780, 550], [1140, 550]], { w: 8, color: 'white', smooth: true, taper: .1 }, 10.5, 0.4);
  add([arr]);

  const ip = add(writeLatin('93.184.216.34', 1350, 550, 60, 11.2, { seed: 12, lspeed: 150 }));
  text('ip', '93.184.216.34', 'FL', ip);

  // Final checkmark
  const check = line([[1650, 530], [1680, 570], [1730, 510]], { w: 8, color: 'white', smooth: true, taper: .1 }, 14.0, 0.4);
  add([check]);

  return { S, TX, EV, SUBS };
}

