import { clamp, lerp, ss, eio, eo } from '/core/lib.js';
import { Stroke, catmull, n1, rng } from './chalk.js';
import { writeLatin, latinWidth, loadSvgFont } from './hand.js';
import { PW } from './stage.js';

export const VO = { n1: 4.361, n2: 4.679, n3: 8.853 };
export const SUB = {
  n1: [['When you type a website name,', 'When you type a website name,'], ['your computer needs an IP address.', 'your computer needs an IP address.']],
  n2: [['DNS acts as the internet\u2019s phonebook,', 'DNS acts as the internet\u2019s phonebook,'], ['translating words into numbers.', 'translating words into numbers.']],
  n3: [['It looks up example.com', 'It looks up example.com'], ['and returns 93.184.216.34.', 'and returns 93.184.216.34.']]
};

export const EV = [];

export function build(W, H) {
  const S = [];
  const add = (strokes, layer = 'FL') => {
    for (const s of strokes) s.layer = layer;
    S.push(...strokes);
    return strokes;
  };

  let t = 0.5;

  // Title
  const title = add(writeLatin('How DNS Works', 1200, 250, 80, t, { seed: 10, speed: 60, lspeed: 100 }));
  t = title.end + 0.8;

  // Step 1: User types example.com
  const line1 = add(writeLatin('1. You type: example.com', 800, 550, 55, t, { seed: 11, speed: 50, lspeed: 90 }));
  t = line1.end + 0.8;

  const line1sub = add(writeLatin('Computer needs an IP address to find the server.', 900, 670, 42, t, { seed: 12, speed: 45, lspeed: 80 }));
  t = line1sub.end + 1.2;

  // Step 2: DNS Phonebook lookup
  const line2 = add(writeLatin('2. DNS Phonebook Lookup', 800, 900, 55, t, { seed: 13, speed: 50, lspeed: 90 }));
  t = line2.end + 0.8;

  const line2sub = add(writeLatin('Translating domain name into numeric IP address...', 900, 1020, 42, t, { seed: 14, speed: 45, lspeed: 80 }));
  t = line2sub.end + 1.2;

  // Step 3: Result IP address
  const line3 = add(writeLatin('3. Resolved IP: 93.184.216.34', 800, 1250, 58, t, { seed: 15, speed: 50, lspeed: 90 }));
  t = line3.end + 1.5;

  return S;
}

