`app.js` expects `F` returned by `build(W, H)` to have:
- `F.S`: array of strokes
- `F.DUR`: total duration in seconds
- `F.EV`: events array
- `F.G1`, `F.G2`: painted grids (or empty/defined objects)
- `F.SMALL`: small grids array
- `F.camAt(t)`: camera function returning `{ cx, cy, s, shot }`
- `F.slideX(t)`: panel slide offset
- `F.wet`: wet band object `{ t0, t1, bx0, xEnd, y0, y1 }`
- `F.wipe`: wipe object `{ t0, t1, path, w }`

Let's check how `dns-chalkboard/js/film.js` can be written to satisfy all these properties expected by `app.js`.
Let's design `dns-chalkboard/js/film.js` properly:
```js
import { clamp, lerp, ss, eio, eo } from '/core/lib.js';
import { Stroke, catmull, n1, rng } from './chalk.js';
import { writeChar, writeLine, writeLatin, latinWidth } from './hand.js';
import { PW, BH } from './stage.js';

export const G1 = { x: 1150, y: 800, size: 620 }, G2 = { x: 2200, y: 800, size: 620 };
export const SMALL = [{ x: 560, y: 1330, size: 300 }];

export const VO = { n1: 4.361, n2: 4.679, n3: 8.853 };
export const SUB = {
  n1: [['When you type a website name,', 'When you type a website name,'], ['your computer needs an IP address.', 'your computer needs an IP address.']],
  n2: [['DNS acts as the internet\u2019s phonebook,', 'DNS acts as the internet\u2019s phonebook,'], ['translating words into numbers.', 'translating words into numbers.']],
  n3: [['It looks up example.com', 'It looks up example.com'], ['and returns 93.184.216.34.', 'and returns 93.184.216.34.']]
};

export function build(W = 1920, H = 1080) {
  const S = [], TX = [], EV = [];
  const add = (arr, layer = 'FL', phase = 'pre') => {
    arr.forEach(s => { s.layer = layer; s.phase = phase; S.push(s); });
    return arr;
  };
  const line = (pts, o, t0, dur) => {
    const s = new Stroke(o.smooth ? catmull(pts, 10) : pts, { kind: 'write', taper: .2, taperLen: .2, land: .6, skip: .14, endSpecks: true, specks: .6, ...o });
    s.t0 = t0; s.t1 = t0 + dur; return s;
  };

  let t = 0.5;
  const title = add(writeLatin('How DNS Works', 1200, 250, 80, t, { seed: 10, speed: 60, lspeed: 100 }));
  t = title.end + 0.5;

  const l1 = add(writeLatin('1. You type: example.com', 800, 500, 55, t, { seed: 11, speed: 50, lspeed: 90 }));
  t = l1.end + 0.4;
  const l1sub = add(writeLatin('Computer needs an IP address to find the server.', 900, 600, 42, t, { seed: 12, speed: 45, lspeed: 80 }));
  t = l1sub.end + 0.8;

  const l2 = add(writeLatin('2. DNS Phonebook Lookup', 800, 800, 55, t, { seed: 13, speed: 50, lspeed: 90 }));
  t = l2.end + 0.4;
  const l2sub = add(writeLatin('Translating domain name into numeric IP address...', 900, 900, 42, t, { seed: 14, speed: 45, lspeed: 80 }));
  t = l2sub.end + 0.8;

  const l3 = add(writeLatin('3. Resolved IP: 93.184.216.34', 800, 1150, 58, t, { seed: 15, speed: 50, lspeed: 90 }));
  t = l3.end + 1.5;

  const DUR = +Math.max(t + 1.0, 20.0).toFixed(2);

  // Mock wet, wipe, camAt, slideX to satisfy app.js
  const wet = { t0: 0.1, t1: 2.0, bx0: 100, xEnd: 3000, y0: 100, y1: 1500 };
  const wipe = { t0: 5.0, t1: 5.5, path: [[100, 100], [100, 1500]], w: 50 };
  const camAt = tt => ({ cx: 1600, cy: 850, s: 0.65, shot: 0 });
  const slideX = tt => 0;

  return { S, EV, DUR, wet, wipe, camAt, slideX, G1, G2, SMALL };
}
