```js
import { clamp, lerp, ss, eio, eo } from '/core/lib.js';
import { Stroke, catmull, n1, rng } from './chalk.js';
import { writeChar, writeLine, writeLatin, latinWidth } from './hand.js';
import { PW, BH } from './stage.js';

export const G1 = { x: 1150, y: 800, size: 620 }, G2 = { x: 2200, y: 800, size: 620 };
export const SMALL = [{ x: 560, y: 1330, size: 300 }];

export const VO = { n1: 4.361, n2: 4.679, n3: 8.853 };

export function build(W = 1920, H = 1080) {
  const S = [], EV = [], SUBS = [], TX = [], T = {};
  const add = (arr, layer = 'FL', phase = 'pre') => {
    arr.forEach(s => { s.layer = layer; s.phase = phase; S.push(s); });
    return arr;
  };
  const line = (pts, o, t0, dur) => {
    const s = new Stroke(pts, { kind: 'write', taper: .2, taperLen: .2, land: .6, skip: .14, endSpecks: true, specks: .6, ...o });
    s.t0 = t0; s.t1 = t0 + dur; return s;
  };

  let t = 0.5;
  const ti = add(writeLatin('How DNS Works', 1000, 252, 100, t, { seed: 4, speed: 22, lspeed: 100 }), 'FL');
  t = ti.end + 0.4;
  const tie = add(writeLatin('The Internet\'s Phoneboard', 1012, 400, 50, t, { seed: 5, lspeed: 150 }), 'FL');
  t = tie.end + 0.5;

  SUBS.push({ id: 'n1', t0: 0.5, t1: 5.0, zh: 'When you type a website name...', en: 'When you type a website name, your computer needs an IP address.' });
  SUBS.push({ id: 'n2', t0: 5.0, t1: 10.0, zh: 'DNS acts as phonebook...', en: 'DNS acts as the internet\'s phonebook, translating words into numbers.' });
  SUBS.push({ id: 'n3', t0: 10.0, t1: 19.0, zh: 'Resolves example.com to IP...', en: 'It looks up example.com and returns 93.184.216.34.' });

  T.back0 = 20.0;
  const DUR = 20.0;

