  const wipe = { t0: 5.0, t1: 5.5, path: [[100, 100], [100, 1500]], w: 50 };
  const camAt = tt => ({ cx: 1920 / 2, cy: 1080 / 2, s: 0.65, shot: 0 });
  const slideX = tt => 0;

  return { S, EV, SUBS, TX, DUR, wet, wipe, camAt, slideX, G1, G2, SMALL, T };
}
